numbers := []int { 2, 7, 42, 1}

Sort_Settings :: struct {
	put_at_end: int,
}

sorting_proc :: proc(i, j: int) -> bool {
	sort_settings := (^Sort_Settings)(context.user_ptr)

	if sort_settings != nil {
		if i == sort_settings.put_at_end {
			return false
		}

		if j == sort_settings.put_at_end {
			return true
		}
	}

	return i < j
}

